"use client";

import { useState, useEffect } from "react";
import Link from "next/link";
import { usePathname } from "next/navigation";
import { Menu, X, Phone, ChevronDown, GraduationCap, Smile } from "lucide-react";
import { siteConfig, institutions } from "@/data/site";

const navLinks = [
  { label: "About", href: "/#about" },
  { label: "Our Institutions", href: "/#institutions", dropdown: true },
  { label: "Careers", href: "/careers" },
  { label: "Contact", href: "/#contact" },
];

const instIcons: Record<string, React.ElementType> = {
  "rainbow-international-school": GraduationCap,
  "rainbow-preschool-international": Smile,
};

export default function Navbar() {
  const [scrolled, setScrolled] = useState(false);
  const [menuOpen, setMenuOpen] = useState(false);
  const [instOpen, setInstOpen] = useState(false);
  const pathname = usePathname();

  // Pages that open with a dark navy hero — the bar sits on dark until scrolled.
  const darkHero =
    pathname === "/" ||
    pathname === "/careers" ||
    pathname.startsWith("/institutions/");

  // "Solid" = white bar with ink text. Otherwise transparent with white text.
  const solid = scrolled || !darkHero;

  useEffect(() => {
    const handler = () => setScrolled(window.scrollY > 20);
    handler();
    window.addEventListener("scroll", handler, { passive: true });
    return () => window.removeEventListener("scroll", handler);
  }, []);

  // Close menus on route change
  useEffect(() => {
    setMenuOpen(false);
    setInstOpen(false);
  }, [pathname]);

  // py-2.5 is a touch-target allowance, not spacing: tablets get the desktop nav
  // at >=768px but are touch devices, and the 11px text alone is only ~17px tall.
  // The header has a fixed height and centres its items, so this is visually inert.
  const linkBase =
    "text-[11px] font-medium uppercase tracking-[0.14em] py-2.5 transition-colors duration-200";
  const linkColor = solid
    ? "text-[var(--color-ink)] hover:text-[var(--color-navy)]"
    : "text-white/80 hover:text-white";

  return (
    <header
      className={`fixed top-0 inset-x-0 z-50 transition-all duration-300 ${
        solid
          ? "bg-white/90 backdrop-blur-xl shadow-[0_1px_0_0_rgba(0,0,0,0.06),0_8px_30px_-12px_rgba(40,48,74,0.15)]"
          : "bg-transparent"
      }`}
    >
      <nav className="max-w-7xl mx-auto px-6 lg:px-8 flex items-center justify-between h-20">
        {/* Logo */}
        <Link href="/" className="flex items-center flex-shrink-0">
          <RainbowLogo className="h-9 w-auto" light={!solid} />
        </Link>

        {/* Desktop links */}
        <ul className="hidden md:flex items-center gap-9">
          {navLinks.map((link) =>
            link.dropdown ? (
              <li
                key={link.href}
                className="relative"
                onMouseEnter={() => setInstOpen(true)}
                onMouseLeave={() => setInstOpen(false)}
              >
                <Link
                  href={link.href}
                  className={`${linkBase} ${linkColor} flex items-center gap-1.5`}
                >
                  {link.label}
                  <ChevronDown
                    size={12}
                    className={`transition-transform duration-200 ${
                      instOpen ? "rotate-180" : ""
                    }`}
                  />
                </Link>

                {/* Dropdown — links to our own institution pages */}
                <div
                  className={`absolute left-1/2 -translate-x-1/2 top-full pt-4 w-[340px] transition-all duration-200 ${
                    instOpen
                      ? "opacity-100 visible translate-y-0"
                      : "opacity-0 invisible -translate-y-1"
                  }`}
                >
                  <div className="rounded-2xl bg-white shadow-[0_20px_60px_-15px_rgba(40,48,74,0.28)] border border-[var(--color-line-light)] p-2">
                    {institutions.map((inst) => {
                      const Icon = instIcons[inst.id] ?? GraduationCap;
                      const isNavy = inst.color === "navy";
                      return (
                        <Link
                          key={inst.id}
                          href={inst.href}
                          className="flex items-start gap-3 p-3 rounded-xl hover:bg-[var(--color-bg-alt)] transition-colors group/item"
                        >
                          <span
                            className={`w-9 h-9 rounded-lg flex items-center justify-center flex-shrink-0 text-white ${
                              isNavy
                                ? "bg-[var(--color-navy)]"
                                : "bg-[var(--color-coral)]"
                            }`}
                          >
                            <Icon size={16} />
                          </span>
                          <span className="min-w-0">
                            <span className="block text-sm font-medium text-[var(--color-ink)]">
                              {inst.name}
                            </span>
                            <span className="block text-xs text-[var(--color-muted)] mt-0.5">
                              {inst.ageRange}
                            </span>
                          </span>
                        </Link>
                      );
                    })}
                  </div>
                </div>
              </li>
            ) : (
              <li key={link.href}>
                <Link href={link.href} className={`${linkBase} ${linkColor}`}>
                  {link.label}
                </Link>
              </li>
            )
          )}
        </ul>

        {/* Desktop CTA */}
        <div className="hidden md:flex items-center gap-5">
          <a
            href={`tel:${siteConfig.phone.admissions.replace(/\s/g, "")}`}
            className={`flex items-center gap-1.5 ${linkBase} ${linkColor}`}
          >
            <Phone size={13} />
            <span>Admissions</span>
          </a>
          <Link
            href="/#contact"
            className={`shimmer-parent px-5 py-2.5 rounded-full text-[11px] font-medium uppercase tracking-[0.12em] transition-all duration-200 ${
              solid
                ? "bg-[var(--color-navy)] text-white hover:bg-[var(--color-navy-deep)]"
                : "bg-white text-[var(--color-navy-deep)] hover:bg-white/90"
            }`}
          >
            Get in Touch
          </Link>
        </div>

        {/* Mobile hamburger */}
        <button
          className={`md:hidden p-2 ${solid ? "text-[var(--color-ink)]" : "text-white"}`}
          onClick={() => setMenuOpen((v) => !v)}
          aria-label="Toggle menu"
          aria-expanded={menuOpen}
        >
          {menuOpen ? <X size={22} /> : <Menu size={22} />}
        </button>
      </nav>

      {/* Mobile drawer */}
      {menuOpen && (
        <div className="md:hidden bg-white border-t border-[var(--color-line-light)] px-6 pb-6 pt-4 flex flex-col gap-1 shadow-xl">
          {navLinks.map((link) => (
            <Link
              key={link.href}
              href={link.href}
              onClick={() => setMenuOpen(false)}
              className="text-xs font-medium uppercase tracking-[0.14em] text-[var(--color-ink)] py-3 border-b border-[var(--color-line-light)]"
            >
              {link.label}
            </Link>
          ))}

          {/* Institution shortcuts */}
          <div className="pt-3 flex flex-col gap-2">
            {institutions.map((inst) => {
              const Icon = instIcons[inst.id] ?? GraduationCap;
              const isNavy = inst.color === "navy";
              return (
                <Link
                  key={inst.id}
                  href={inst.href}
                  onClick={() => setMenuOpen(false)}
                  className="flex items-center gap-3 p-3 rounded-xl bg-[var(--color-bg-alt)]"
                >
                  <span
                    className={`w-8 h-8 rounded-lg flex items-center justify-center text-white flex-shrink-0 ${
                      isNavy ? "bg-[var(--color-navy)]" : "bg-[var(--color-coral)]"
                    }`}
                  >
                    <Icon size={15} />
                  </span>
                  <span className="text-sm text-[var(--color-ink)]">{inst.name}</span>
                </Link>
              );
            })}
          </div>

          <Link
            href="/#contact"
            onClick={() => setMenuOpen(false)}
            className="mt-3 px-5 py-3.5 rounded-full bg-[var(--color-navy)] text-white text-xs font-medium uppercase tracking-[0.12em] text-center"
          >
            Get in Touch
          </Link>
          <a
            href={`tel:${siteConfig.phone.admissions.replace(/\s/g, "")}`}
            className="flex items-center justify-center gap-2 text-sm text-[var(--color-navy)] font-medium py-2"
          >
            <Phone size={14} />
            {siteConfig.phone.admissions}
          </a>
        </div>
      )}
    </header>
  );
}

